func TestRequestLoggerHijackNotLoggedAsOK(t *testing.T) {
	// A hijacked connection is owned by the handler, so no implicit 200 applies.
	f := &statusCapturingFormatter{}
	handler := RequestLogger(f)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hj, ok := w.(http.Hijacker)
		if !ok {
			t.Fatalf("writer does not implement http.Hijacker")
		}
		if _, _, err := hj.Hijack(); err != nil {
			t.Fatalf("hijack: %v", err)
		}
	}))

	w := testLoggerWriter{ResponseRecorder: httptest.NewRecorder()}
	handler.ServeHTTP(w, httptest.NewRequest("GET", "/", nil))

	if len(f.statuses) != 1 {
		t.Fatalf("expected 1 log write, got %d", len(f.statuses))
	}
	if got := f.statuses[0]; got != 0 {
		t.Errorf("logged status on hijack: got %d, want 0", got)
	}
}
