package middleware

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

type captureEntryFormatter struct{ status *int }

func (f captureEntryFormatter) NewLogEntry(r *http.Request) LogEntry {
	return captureEntry{f.status}
}

type captureEntry struct{ status *int }

func (e captureEntry) Write(status, bytes int, header http.Header, elapsed time.Duration, extra any) {
	*e.status = status
}
func (e captureEntry) Panic(v any, stack []byte) {}

func TestReproEmptyHandlerStatus(t *testing.T) {
	var got = -1
	h := RequestLogger(captureEntryFormatter{&got})(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	w := httptest.NewRecorder()
	h.ServeHTTP(w, httptest.NewRequest("GET", "/", nil))
	if w.Code != 200 {
		t.Fatalf("client status = %d", w.Code)
	}
	if got != 200 {
		t.Fatalf("logged status = %d, want 200", got)
	}
}

func TestReproPanicStillZero(t *testing.T) {
	var got = -1
	h := RequestLogger(captureEntryFormatter{&got})(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { panic("boom") }))
	func() {
		defer func() { recover() }()
		h.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", "/", nil))
	}()
	if got != 0 {
		t.Fatalf("logged status after panic = %d, want 0", got)
	}
	_ = strings.TrimSpace
}
EOF
