func TestPathRewriteEncodedPath(t *testing.T) {
	r := chi.NewRouter()
	r.Use(PathRewrite("/old", "/new"))

	r.Get("/new/{name}", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte(chi.URLParam(r, "name")))
	})

	for _, tc := range []struct{ path, want string }{
		{"/old/xA", "xA"},
		{"/old/x%41", "xA"},
	} {
		w := httptest.NewRecorder()
		req, _ := http.NewRequest("GET", tc.path, nil)
		r.ServeHTTP(w, req)

		if w.Result().StatusCode != http.StatusOK {
			t.Errorf("%s: unexpected response code: %v", tc.path, w.Result().StatusCode)
		}
		if got := w.Body.String(); got != tc.want {
			t.Errorf("%s: got body %q, want %q", tc.path, got, tc.want)
		}
	}
}
EOF
