func TestRedirectSlashesInSubrouter(t *testing.T) {
	r := chi.NewRouter()

	r.Route("/api", func(a chi.Router) {
		a.Use(RedirectSlashes)
		a.Get("/items", func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("items"))
		})
	})

	for _, tc := range []struct{ path, location string }{
		{"/api/items/", "/api/items"},
		{"/api/items/?q=1", "/api/items?q=1"},
	} {
		w := httptest.NewRecorder()
		req, _ := http.NewRequest("GET", tc.path, nil)
		r.ServeHTTP(w, req)

		if w.Result().StatusCode != http.StatusMovedPermanently {
			t.Errorf("%s: unexpected response code: %v", tc.path, w.Result().StatusCode)
		}
		if got := w.Result().Header.Get("Location"); got != tc.location {
			t.Errorf("%s: got Location %q, want %q", tc.path, got, tc.location)
		}
	}

	w := httptest.NewRecorder()
	req, _ := http.NewRequest("GET", "/api/items", nil)
	r.ServeHTTP(w, req)
	if w.Body.String() != "items" {
		t.Errorf("/api/items: got body %q, want %q", w.Body.String(), "items")
	}
}
EOF
