cat > middleware/request_size.go <<'EOF'
package middleware

import (
	"net/http"
)

// RequestSize is a middleware that will limit request sizes to a specified
// number of bytes. If the declared Content-Length is greater than bytes, it
// responds with 413 Request Entity Too Large immediately and does not call the
// next handler. When the size is unknown or within the limit, the body is
// wrapped with MaxBytesReader so reads beyond bytes fail.
func RequestSize(bytes int64) func(http.Handler) http.Handler {
	f := func(h http.Handler) http.Handler {
		fn := func(w http.ResponseWriter, r *http.Request) {
			if r.ContentLength > bytes {
				http.Error(w, http.StatusText(http.StatusRequestEntityTooLarge), http.StatusRequestEntityTooLarge)
				return
			}
			r.Body = http.MaxBytesReader(w, r.Body, bytes)
			h.ServeHTTP(w, r)
		}
		return http.HandlerFunc(fn)
	}
	return f
}
EOF
cat > middleware/request_size_test.go <<'EOF'
package middleware

import (
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestRequestSizeDeclaredTooLarge(t *testing.T) {
	called := false
	h := RequestSize(10)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		called = true
	}))

	req := httptest.NewRequest(http.MethodPost, "/", strings.NewReader(strings.Repeat("a", 11)))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)

	if rec.Code != http.StatusRequestEntityTooLarge {
		t.Fatalf("status = %d, want %d", rec.Code, http.StatusRequestEntityTooLarge)
	}
	if called {
		t.Fatal("next handler was called for oversized Content-Length")
	}
}

func TestRequestSizeDeclaredWithinLimit(t *testing.T) {
	var body string
	h := RequestSize(10)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		b, err := io.ReadAll(r.Body)
		if err != nil {
			t.Fatalf("unexpected read error: %v", err)
		}
		body = string(b)
	}))

	req := httptest.NewRequest(http.MethodPost, "/", strings.NewReader(strings.Repeat("a", 10)))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)

	if body != strings.Repeat("a", 10) {
		t.Fatalf("body = %q", body)
	}
}

func TestRequestSizeUnknownLengthIsLimitedOnRead(t *testing.T) {
	var readErr error
	h := RequestSize(10)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, readErr = io.ReadAll(r.Body)
	}))

	req := httptest.NewRequest(http.MethodPost, "/", io.MultiReader(strings.NewReader(strings.Repeat("a", 20))))
	req.ContentLength = -1
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)

	if readErr == nil {
		t.Fatal("expected read error for body exceeding limit with unknown length")
	}
}
EOF
