// mountPrefix returns the part of the request path that precedes routePath, i.e.
// the prefix consumed by the parent router's mount point. It reports false if
// routePath is not a suffix of the request path. The same source the router
// uses (RawPath when set, otherwise Path) is used so the two line up.
func mountPrefix(r *http.Request, routePath string) (string, bool) {
	full := r.URL.RawPath
	if full == "" {
		full = r.URL.Path
	}
	if !strings.HasSuffix(full, routePath) {
		return "", false
	}
	return full[:len(full)-len(routePath)], true
}
EOF
