	var got string
	var readErr error
	h := RequestSize(10)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var b strings.Builder
		_, readErr = b.ReadFrom(r.Body)
		got = b.String()
	}))
	req := httptest.NewRequest(http.MethodPost, "/", strings.NewReader(strings.Repeat("a", 10)))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if readErr != nil || len(got) != 10 {
		t.Fatalf("got %d bytes, err %v", len(got), readErr)
	}
}

func TestRequestSizeUnknownLengthLimitedOnRead(t *testing.T) {
	var readErr error
	h := RequestSize(10)(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var b strings.Builder
		_, readErr = b.ReadFrom(r.Body)
	}))
