func TestPathRewriteRawPath(t *testing.T) {
	handler := func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte(chi.URLParam(r, "name")))
	}

	serve := func(r http.Handler, path string) (int, string) {
		w := httptest.NewRecorder()
		req, err := http.NewRequest("GET", path, nil)
		if err != nil {
			t.Fatal(err)
		}
		r.ServeHTTP(w, req)
		return w.Result().StatusCode, w.Body.String()
	}

	// Reference: the same paths requested directly, without any rewrite.
	direct := chi.NewRouter()
	direct.Get("/new/{name}", handler)

	rewritten := chi.NewRouter()
	rewritten.Use(PathRewrite("/old", "/new"))
	rewritten.Get("/new/{name}", handler)

	for _, p := range []string{"/new/xA", "/new/x%41", "/new/a%2Fb", "/new/a%2Fb%41"} {
		want, wantBody := serve(direct, p)
		if want != http.StatusOK {
			t.Fatalf("reference %s: unexpected status %d", p, want)
		}

		old := "/old" + p[len("/new"):]
		got, gotBody := serve(rewritten, old)
		if got != want || gotBody != wantBody {
			t.Errorf("%s: got (%d, %q), want (%d, %q)", old, got, gotBody, want, wantBody)
		}
	}
}

func TestRewriteRawPathHelpers(t *testing.T) {
	cases := []struct {
		raw, old, new, want string
		start, n            int
	}{
		{"/old/x%41", "/old", "/new", "/new/x%41", 0, 4},
		{"/a/%6Fld/b", "/old", "/new", "/a/%6Fld/b", 0, 0}, // no-op guard handled by caller
		{"/%6Fld/old/x", "/old", "/new", "/%6Fld/new/x", 5, 4},
	}
	for _, c := range cases {
		if c.n == 0 {
			continue
		}
		if got := rewriteRawPath(c.raw, c.start, c.n, c.new); got != c.want {
			t.Errorf("rewriteRawPath(%q, %d, %d, %q) = %q, want %q", c.raw, c.start, c.n, c.new, got, c.want)
		}
	}

	// A raw path that does not decode to the expected offsets must not be trusted.
	if got := rewriteRawPath("/a", 0, 10, "/x"); got != "" {
		t.Errorf("rewriteRawPath on short raw path = %q, want empty", got)
	}
}
